class Solution:
 def sortSentence(self,s):
  words=s.split();a=['']*len(words)
  for w in words:a[int(w[-1])-1]=w[:-1]
  return ' '.join(a)

class Solution:
 def subsetXORSum(self,nums):
  ans=0
  for mask in range(1<<len(nums)):
   x=0
   for i,v in enumerate(nums):
    if mask>>i&1:x^=v
   ans+=x
  return ans

class Solution:
 def isSumEqual(self,firstWord,secondWord,targetWord):
  def val(w):return int(''.join(str(ord(c)-97) for c in w))
  return val(firstWord)+val(secondWord)==val(targetWord)

class Solution:
 def findRotation(self,mat,target):
  cur=mat
  for _ in range(4):
   if cur==target:return True
   cur=[list(row) for row in zip(*cur[::-1])]
  return False

class Solution:
 def largestOddNumber(self,num):
  for i in range(len(num)-1,-1,-1):
   if int(num[i])%2:return num[:i+1]
  return ''

